diff --git a/src/compiler/compiler.cpp b/src/compiler/compiler.cpp
index 8cb0bec..5803ce7 100644
--- a/src/compiler/compiler.cpp
+++ b/src/compiler/compiler.cpp
@@ -27,6 +27,10 @@
 #include "llvm/Object/ObjectFile.h"
 #include "llvm/Support/SmallVectorMemoryBuffer.h"
 #include <deque>
+#include <cstdlib>
+#include <cstdio>
+#include <functional>
+#include <unordered_map>

 #if defined(ZEN_ENABLE_MULTIPASS_JIT_LOGGING) || defined(ZEN_ENABLE_LINUX_PERF)
 #include "utils/asm_dump.h"
@@ -401,6 +405,42 @@ void WasmJITCompiler::compileWasmToMC(WasmFrontendContext &Ctx, MModule &Mod,
   MIRBuilder.compile(&Ctx); // pass the ctx argument only for compatibility
   runtime::Runtime *RT = WasmMod->getRuntime();
   const runtime::RuntimeConfig &Config = RT->getConfig();
+  // Research-only, opt-in static intervention. No case or function IDs.
+  if (DisableGreedyRA && Config.EnableMultipassLazy &&
+      !Config.DisableMultipassGreedyRA &&
+      std::getenv("DTVM_RESEARCH_PURE_LOOP_GREEDY") &&
+      FuncCode->CodeSize <= 768 && FuncCode->NumLocals <= 32 &&
+      FuncCode->Stats == runtime::Module::SF_none &&
+      MFunc.getNumBasicBlocks() <= 64) {
+    bool HasCall = false;
+    std::function<void(const MInstruction *)> VisitExpr =
+        [&](const MInstruction *Inst) {
+          HasCall |= Inst->getOpcode() == OP_call || Inst->getOpcode() == OP_icall;
+          for (OperandNum I = 0; I < Inst->getNumOperands(); ++I) {
+            if (const MInstruction *Op = Inst->getOperand(I)) VisitExpr(Op);
+          }
+        };
+    for (const MBasicBlock *BB : MFunc)
+      for (const MInstruction *Inst : *BB) VisitExpr(Inst);
+    std::unordered_map<const MBasicBlock *, unsigned> Colors;
+    std::function<bool(const MBasicBlock *)> HasCycle =
+        [&](const MBasicBlock *BB) {
+          unsigned &Color = Colors[BB];
+          if (Color == 1) return true;
+          if (Color == 2) return false;
+          Color = 1;
+          for (const MBasicBlock *Succ : BB->successors())
+            if (HasCycle(Succ)) return true;
+          Colors[BB] = 2;
+          return false;
+        };
+    if (!HasCall && HasCycle(MFunc.getEntryBasicBlock())) {
+      DisableGreedyRA = false;
+      if (std::getenv("DTVM_RESEARCH_SELECTION_LOG"))
+        std::fprintf(stderr, "PURE_LOOP_GREEDY %u %u %u\n", FuncIdx,
+                     FuncCode->CodeSize, MFunc.getNumBasicBlocks());
+    }
+  }
   compileMIRToCgIR(Mod, MFunc, CgFunc, DisableGreedyRA);
   Ctx.getMCLowering().runOnCgFunction(CgFunc);
 }
